import{_ as o,o as i,c as a,a2 as t}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0042 — Token di path legati al file (formato enc2)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0042-path-token-legato-al-file.md","filePath":"adr/0042-path-token-legato-al-file.md"}'),c={name:"adr/0042-path-token-legato-al-file.md"};function n(l,e,d,r,s,p){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="adr-0042-—-token-di-path-legati-al-file-formato-enc2" tabindex="-1">ADR-0042 — Token di path legati al file (formato enc2) <a class="header-anchor" href="#adr-0042-—-token-di-path-legati-al-file-formato-enc2" aria-label="Permalink to &quot;ADR-0042 — Token di path legati al file (formato enc2)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.2 (2026-11-02): §3.2.2, §3.4.3, §3.8.3, §3.8.5, §3.8.7 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-11-01</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§3.8.1 (modello di minaccia, A3 server attivamente malevolo), §3.8.3 (path cifrati), §3.8.5, §3.8.7 (test vector); D-02; ADR-0009</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì (§3.8.3 e §3.8.7) → nuovo formato del token di path accanto a <code>enc1:</code>; richiede aggiornamento di <code>Specifications.md</code> da parte dell&#39;owner</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Nei vault privati il server conserva per ogni file un token di path opaco (<code>files.path</code>, <code>file_revisions.path</code>) e una chiave di unicità deterministica (<code>files.path_key</code>):</p><ul><li><code>enc1:</code> + base64url(nonce(12) ‖ AES-256-GCM(K_path_enc, path NFC; AAD = <code>vault_id</code>) ‖ tag(16)), con nonce casuale;</li><li><code>hmac1:</code> + hex(HMAC-SHA256(K_path_key, NFC + casefold(path))), su cui il server applica <code>PATH_COLLISION</code> senza conoscere il path (ADR-0009).</li></ul><p>L&#39;AAD di <code>enc1</code> contiene solo <code>vault_id</code>, mentre l&#39;AAD dei blob contiene anche il <code>file_id</code> (<code>crypto-design.md</code> §5.1). La review del 2026-11-01 (rilievo <em>path-token-not-bound-to-file</em>) ne ricava uno scenario dell&#39;avversario A3: in <code>GET /changes</code> o in <code>GET /tree</code> il server associa al file X il token di path del file Y (e il suo <code>hmac1</code>). Il client decifra entrambi senza errore e scrive il contenuto di X al path di Y: per esempio una nota sostituita dal contenuto di un&#39;altra sotto un nome fidato. Il server non impara nulla e il danno resta dentro i dati dell&#39;utente, ma è un&#39;alterazione dell&#39;integrità non rilevata, che il modello di minaccia dichiara coperta. <code>crypto-design.md</code> §8 non la elencava tra i limiti.</p><p>Vincoli:</p><ul><li><strong>compatibilità</strong>: i vault privati esistenti hanno solo token <code>enc1</code> e devono continuare a funzionare su ogni client (desktop, core WASM del workbench web, export ZIP del browser in <code>packages/vaultcrypto-web</code>);</li><li><strong>D-02, nessun lockout</strong>: nessun passo della migrazione può rendere illeggibile un vault a un dispositivo aggiornato;</li><li>il token si riscrive solo quando un file nasce o si sposta (create, move, modify di un file revocato): un file mai spostato conserva il suo <code>enc1</code> per sempre, salvo migrazione esplicita.</li></ul><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><p><strong>Formato enc2.</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>enc2 = &quot;enc2:&quot; + base64url(nonce (12) ‖ AES-256-GCM(K_path_enc, path NFC; AAD) ‖ tag (16))</span></span>
<span class="line"><span>AAD  = &quot;memobrain/v2/path&quot; (17 B ASCII) ‖ vault_id (16 B) ‖ file_id (16 B)</span></span></code></pre></div><ul><li>Stessa chiave <code>K_path_enc</code> di <code>enc1</code>, stesso nonce casuale a 96 bit. Le due AAD hanno lunghezze diverse (16 e 49 byte) e la v2 ha un prefisso di dominio: un token rietichettato da una versione all&#39;altra non si apre (né l&#39;upgrade <code>enc1→enc2</code> né il downgrade <code>enc2→enc1</code>).</li><li>Il prefisso è la versione: il server lo convalida per forma senza capirlo, come oggi <code>enc1:</code>.</li><li><strong><code>hmac1</code> non cambia</strong>: dipende solo dal path, non dalla versione del token né dal <code>file_id</code>. Unicità (<code>PATH_COLLISION</code>), ricerca per prefisso e deduplica sul server restano identiche, anche in un vault misto <code>enc1</code>/<code>enc2</code>.</li></ul><p><strong>Lettura (tutti i client).</strong> <code>DecryptPathFor(sub, vault_id, file_id, token)</code> in Go e <code>decryptPathFor(...)</code> in TS accettano <code>enc1</code> (controllato sul vault) ed <code>enc2</code> (controllato su vault e file). <code>DecryptPath</code> senza <code>file_id</code> resta e legge solo <code>enc1</code>. Il motore di sync passa sempre il <code>file_id</code> della change o della voce del tree; l&#39;export ZIP passa il <code>file_id</code> della voce del manifest.</p><p><strong>Scrittura.</strong> Il client scrive <code>enc2</code> solo se:</p><ul><li>il flag del Config Profile <code>features.path_v2</code> è acceso (<strong>spento per default</strong> nel rilascio N), oppure</li><li>il vault è annotato come già passato a <code>enc2</code> su questo dispositivo (pin di vault, sotto).</li></ul><p>Altrimenti scrive <code>enc1</code>, che ogni client sa leggere.</p><p><strong>Pinning</strong> (trust on first use, come ADR-0034; solo client desktop e core WASM, che hanno <code>sync.db</code>):</p><ul><li><strong>pin di vault</strong> <code>path_v2:&lt;id cloud&gt;</code> in <code>sync_meta</code>: si accende quando il motore decifra un token <code>enc2</code> di quel vault o quando il server accetta un <code>enc2</code> scritto da questo dispositivo. Da quel momento i nuovi token restano <code>enc2</code> anche a flag spento: un vault non torna mai a <code>enc1</code>. L&#39;id cloud è nella chiave, così una cartella ricollegata a un altro vault non eredita il pin.</li><li><strong>pin di file</strong> <code>path_v2_file:&lt;file_id&gt;</code>: si accende alle stesse condizioni, per quel file. Da quel momento un token <code>enc1</code> per quel file è rifiutato (<code>ErrPathDowngrade</code>) e la change finisce in quarantena (ADR-0039), senza toccare il file locale. Un file mai visto in <code>enc2</code> continua ad accettare <code>enc1</code>, che usa legittimamente finché non viene spostato.</li></ul><p>Il pin di file non produce falsi positivi tra client del rilascio N: per scrivere il path di un file (move, revive) un client deve averne l&#39;ultima revisione (<code>base_rev</code>), quindi ha già decifrato il suo <code>enc2</code>, ha acceso il pin di vault e scrive <code>enc2</code>. Un client anteriore al rilascio N non sa decifrare <code>enc2</code>: mette la change in quarantena e non scrive mai quel file.</p><p><strong>Migrazione in due rilasci</strong> (stesso schema di ADR-0034):</p><ol><li><strong>Rilascio N (questo):</strong> tutti i client leggono <code>enc1</code> ed <code>enc2</code>. Si scrive ancora <code>enc1</code>, salvo con <code>features.path_v2</code> acceso o vault annotato. Il pinning è attivo.</li><li><strong>Rilascio N+1:</strong><ul><li><code>features.path_v2</code> diventa acceso per default;</li><li>migrazione dei token rimasti <code>enc1</code>: il client, a vault sbloccato, riscrive in <code>enc2</code> il path dei file che ne hanno ancora uno <code>enc1</code> (un move verso lo stesso path, stesso <code>hmac1</code>), in lotti e in background;</li><li>quando un tree completo non contiene più token <code>enc1</code>, il client accende un <strong>pin forte</strong> di vault e da lì rifiuta qualunque <code>enc1</code>.</li></ul></li></ol><p><strong>Server.</strong> Oggi <code>resolvePath</code> (<code>services/cloud/internal/sync/service.go</code>) accetta solo token che iniziano con <code>enc1:</code>. Deve accettare anche <code>enc2:</code>, con gli stessi controlli di forma (lunghezza, alfabeto base64url, niente separatori). Nessuna migrazione dello schema: <code>path</code> è già <code>TEXT</code>. Questa modifica server è un <strong>prerequisito</strong> per accendere <code>features.path_v2</code>: con il server attuale un commit <code>enc2</code> è rifiutato con <code>PATH_INVALID</code> e il file resta parcheggiato con l&#39;errore, senza perdita di dati. <code>syncproto.IsOpaquePath</code> (oggi usato solo da <code>Op.Validate</code> nei test) va allineato allo stesso modo. Per il rilascio N+1 il server deve anche accettare un move il cui <code>path_key</code> resta quello del file stesso.</p><p><strong>Test vector.</strong></p><ul><li><code>shared/conformance/crypto/vectors.json</code>: nuova sezione <code>paths_v2</code> (vault, file, path, nonce, AAD in esadecimale, token, <code>hmac1</code>), con lo stesso path cifrato per due <code>file_id</code> diversi.</li><li><code>negative-vectors.json</code>, sezione <code>paths</code> (campo opzionale <code>file_id</code>): token <code>enc2</code> alterato, di un altro file (<code>file_id</code> scambiato), di un altro vault, <code>enc2</code> rietichettato <code>enc1</code> (downgrade), <code>enc1</code> rietichettato <code>enc2</code> (upgrade forgiato), <code>enc2</code> troncato e non base64url, prefisso sconosciuto <code>enc3:</code>.</li><li>Go (<code>shared/go/vaultcrypto</code>) e TS (<code>packages/vaultcrypto-web</code>) li verificano entrambi; il motore di sync ha test con cifratura reale per scambio, downgrade e scrittura governata dal flag (<code>apps/desktop/internal/sync/pathv2_test.go</code>).</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Documentare il limite e non cambiare formato</strong> — scartata come stato finale: il costo è piccolo (un prefisso, 32 byte di AAD) e chiude l&#39;unico dato cifrato non legato al file. Resta la situazione dei vault non migrati durante il rilascio N, documentata in <code>crypto-design.md</code> §8.</li><li><strong>Mettere il <code>file_id</code> nell&#39;AAD di <code>enc1</code> senza cambiare prefisso</strong> — scartata: i token esistenti non si aprirebbero più (lockout, contrario a D-02), e senza versione esplicita il client dovrebbe provare entrambe le AAD a ogni lettura.</li><li><strong>Una sottochiave nuova per <code>enc2</code></strong> (<code>memobrain/v2/path-enc</code>) — non necessaria: la separazione tra le versioni è data dall&#39;AAD, e una chiave in più va derivata, testata e cancellata su ogni client.</li><li><strong>Pin solo di vault, che rifiuta ogni <code>enc1</code> dopo il primo <code>enc2</code></strong> — scartata per il rilascio N: in un vault misto i file mai spostati hanno legittimamente <code>enc1</code> e finirebbero in quarantena. Diventa il pin forte del rilascio N+1, dopo la migrazione.</li><li><strong>Legare anche <code>hmac1</code> al <code>file_id</code></strong> — scartata: la chiave di unicità deve essere uguale per due file con lo stesso path, altrimenti il server non potrebbe più rilevare <code>PATH_COLLISION</code>.</li><li><strong>Scrivere <code>enc2</code> subito</strong> — scartata: i dispositivi non aggiornati non leggerebbero più i file nuovi o spostati, e il server attuale rifiuta il prefisso.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Uno scambio di token di path tra file dello stesso vault viene rilevato per ogni file <code>enc2</code>: decifratura fallita, change in quarantena, file locale intatto. Durante il rilascio N restano esposti i file che hanno ancora <code>enc1</code> e che il dispositivo non ha mai visto in <code>enc2</code>, e l&#39;export ZIP del browser (senza stato persistente) per i file <code>enc1</code>.</li><li>La cronologia del desktop (<code>Manager.History</code>, <code>apps/desktop/internal/sync/manager_ops.go</code>) usa ancora <code>DecryptPath</code> senza <code>file_id</code>: per una revisione con token <code>enc2</code> il path apparirebbe vuoto. Va passata a <code>DecryptFilePath(row.FileID, r.Path)</code> prima di accendere il flag.</li><li>Il flag <code>features.path_v2</code> va collegato in <code>apps/desktop/internal/app</code> (accanto a <code>features.envelope_v2</code>, con <code>sync.Manager.SetPathV2</code>), documentato nella guida admin ed elencato nelle due copie dello schema del Config Profile.</li><li>Il server va aggiornato come descritto sopra prima di accendere il flag.</li><li>Da aggiornare nello spec: §3.8.3, riga del path cifrato (<code>enc2:</code> con AAD <code>&quot;memobrain/v2/path&quot; ‖ vault_id ‖ file_id</code>, <code>enc1:</code> accettato in lettura); §3.8.5 (il server accetta i due prefissi); §3.8.7 (vettori <code>paths_v2</code> e negativi, regola del pinning).</li></ul><h2 id="esito" tabindex="-1">Esito <a class="header-anchor" href="#esito" aria-label="Permalink to &quot;Esito&quot;">​</a></h2><p>Stato dell&#39;implementazione al 2026-11-01: <strong>rilascio N completato lato client</strong>, in attesa della modifica server. Lo stato resta «proposta» finché l&#39;owner non accetta l&#39;ADR e aggiorna lo spec.</p><p><strong>Aggiornamento 2026-11-02:</strong> l&#39;owner ha accettato l&#39;ADR, recepito in <code>Specifications.md</code> v1.2. Il server accetta ora anche i token <code>enc2:</code> (<code>resolvePath</code> in <code>services/cloud/internal/sync/service.go</code> e <code>syncproto.IsOpaquePath</code>), prerequisito per accendere <code>features.path_v2</code>.</p><ul><li><strong>Libreria Go</strong> (<code>shared/go/vaultcrypto/path.go</code>): <code>EncryptPathV2</code>/<code>EncryptPathV2WithNonce</code>, <code>DecryptPathFor</code>, <code>PathAADV2</code>, <code>PathTokenVersion</code>, <code>PathEncPrefixV2</code>. <code>EncryptPath</code> (enc1) resta lo scrittore di default; <code>DecryptPath</code> legge solo <code>enc1</code>.</li><li><strong>Libreria TS</strong> (<code>packages/vaultcrypto-web/src/path.ts</code>): <code>encryptPathV2</code>, <code>decryptPathFor</code>, <code>pathAadV2</code>, <code>pathTokenVersion</code>, <code>PATH_ENC_PREFIX_V2</code>. L&#39;export ZIP decifra i path con <code>decryptPathFor</code> e il <code>file_id</code> della voce; l&#39;API esistente non cambia (nessuna modifica a <code>web/src/export</code>).</li><li><strong>Client desktop e core WASM</strong>: <code>sync.Cipher</code> espone <code>PathV2()</code>, <code>EncryptPath(fileID, path, v2)</code> e <code>DecryptFilePath(fileID, token)</code>; il motore applica pin e scelta del formato (<code>pull.go</code>, <code>push.go</code>); <code>crypto.Manager.SetPathV2</code> e <code>sync.Manager.SetPathV2</code> ricevono il flag.</li><li><strong>Prima di scrivere un token</strong> il client applica anche la regola completa dei nomi riservati di Windows (<code>pathrules.NormalizePortable</code>), perché per i vault privati il server non può controllare i nomi.</li></ul><p><strong>Rilascio N+1 (2026-11-02).</strong> L&#39;owner ha deciso di eseguire il rilascio N+1, con le tre azioni della decisione.</p><ol><li><p><strong><code>features.path_v2</code> acceso per default.</strong> <code>default: true</code> in <code>api/config-profile.schema.json</code>, da cui si generano le costanti Go e TS (<code>task gen-features</code>). Tutti i consumatori leggono quelle:</p><ul><li>i default del prodotto distribuiti dal cloud (<code>configprofiles.ProductDefaults</code>);</li><li><code>crypto.NewManager</code>, dove <code>Options.PathV2</code> è ora un <code>*bool</code> e <code>nil</code> prende il default;</li><li><code>pathV2Enabled</code> del desktop e del core WASM (<code>apps/desktop/internal/app/managed.go</code>).</li></ul><p>Un client senza profilo scrive quindi <code>enc2</code>. Un amministratore può spegnere il flag. Spento, il client non migra, ma un vault annotato continua a scrivere <code>enc2</code>, e un pin forte già acceso resta.</p></li><li><p><strong>Migrazione in background</strong> (<code>apps/desktop/internal/sync/pathmigrate.go</code>, chiamata da <code>Engine.Sync</code>). Con il flag acceso e il vault sbloccato, il client riscrive in <code>enc2</code> i token <code>enc1</code> rimasti.</p><ul><li><strong>Operazione:</strong> un <code>move</code> verso lo stesso path, con lo stesso <code>hmac1</code> e la <code>base_rev</code> del file. Il contenuto non cambia. Il server la accetta già: <code>move</code> in <code>services/cloud/internal/sync/ops.go</code> ammette un <code>path_key</code> occupato dal file stesso e rifiuta solo un token identico, e un token nuovo ha sempre un nonce nuovo. Lo verifica <code>TestPrivateVaultAcceptsEnc2PathTokens</code>, nei test d&#39;integrazione del cloud.</li><li><strong>Quando:</strong> solo alla fine di un ciclo di sync che non ha trovato altro da fare (scan, pull, risoluzione e push a vuoto), mai con una sincronizzazione richiesta in attesa né con il vault bloccato.</li><li><strong>Ritmo:</strong> un lotto per ciclo (<code>pathMigrationBatch</code>, 100 file, un solo commit), almeno 15 s tra due lotti (<code>pathMigrationSpacing</code>) e al massimo 30 s di lavoro per lotto. Lo scheduler torna dopo 15 s finché restano lotti (<code>Engine.MigrationPending</code>). Se nessun file si può riscrivere, il controllo successivo arriva dopo 15 minuti.</li><li><strong>Quali file:</strong> <code>GET /tree</code> si legge una volta per passaggio; i token <code>enc1</code> formano una coda in memoria. Un file entra in un lotto solo se è sincronizzato alla stessa revisione dell&#39;albero e non ha modifiche locali, candidati al merge (<code>pending_remote</code>), errori o tentativi falliti. Il suo token deve inoltre decifrarsi (pin di file compresi) nel path locale. Gli altri file restano a un passaggio successivo.</li><li><strong>Esiti:</strong> un conflitto (il file è cambiato sul server) non tocca il file: il pull porta la modifica e il file si riprende alla nuova revisione. Un rifiuto è registrato per quella revisione, per la durata del processo, e non si ritenta. Un errore viene registrato nel log e non fa mai fallire il ciclo. Un move accettato aggiorna <code>server_rev</code> e <code>base_rev</code> della riga e accende il pin di file.</li><li><strong>Ripresa:</strong> il progresso è l&#39;albero del server, perché un file migrato ha un <code>enc2</code>. <code>sync_meta</code> tiene in <code>path_v2_migration:&lt;id cloud&gt;</code> (JSON) i file riscritti, quelli rimasti all&#39;ultima lettura, l&#39;ora del lotto successivo e la fine della migrazione. Dopo un riavvio la migrazione riprende con lo stesso ritmo.</li></ul></li><li><p><strong>Pin forte</strong> <code>path_v2_strong:&lt;id cloud&gt;</code>, insieme al pin di vault, nella stessa transazione. Si accende quando un albero completo ha almeno un file e nessun token <code>enc1</code>, e il cursore del client ha già raggiunto il suo <code>as_of_seq</code>: così una change <code>enc1</code> più vecchia, ancora da scaricare, non viene rifiutata. Da quel momento <code>clearPath</code> rifiuta ogni token <code>enc1</code> del vault con <code>ErrPathDowngrade</code>: la change va in quarantena (ADR-0039) e il file locale non viene toccato. Un vault vuoto non riceve il pin: non ha token da proteggere, e un client che non ha mai visto <code>enc2</code> potrebbe crearvi il primo file in <code>enc1</code>.</p></li></ol><p>Test:</p><ul><li>unitari, con un server simulato il cui albero e changelog seguono i commit (<code>apps/desktop/internal/sync/pathmigrate_test.go</code>): lotti limitati, stesso <code>hmac1</code> e <code>base_rev</code>, file con una modifica locale lasciato fuori e niente pin forte finché resta, pin forte dopo l&#39;ultimo token, <code>enc1</code> in quarantena dopo il pin, ritmo e ripresa dopo un riavvio, nessuna migrazione a flag spento, conflitto senza effetti sul file. Girano anche nel core WASM;</li><li>d&#39;integrazione con il cloud reale (<code>TestPrivateVaultPathMigration</code> in <code>apps/desktop/internal/sync/e2e_pathv2_test.go</code>): vault scritto da un client del rilascio N (flag spento) con soli <code>enc1</code>, migrato da un client con la configurazione predefinita, pin forte dopo l&#39;ultimo token, un <code>enc1</code> successivo in quarantena, il client a flag spento che legge tutto e, con il vault annotato, scrive <code>enc2</code>.</li></ul><p>Limiti:</p><ul><li>Le revisioni dello storico conservano il token con cui sono state scritte. La cronologia le decifra con <code>DecryptFilePath</code> e il pin forte non la riguarda.</li><li>Un file cancellato prima della migrazione e ripristinato dopo il pin forte torna con il suo ultimo token, <code>enc1</code>: i dispositivi con il pin forte lo mettono in quarantena, e i dati restano sul server.</li><li>L&#39;export ZIP del browser non ha stato e continua ad accettare <code>enc1</code>.</li></ul><p><strong>Compatibilità.</strong> I desktop fino alla 1.2.4 non leggono i token <code>enc2</code>: saltano i file nuovi e spostati e, ripartendo dall&#39;albero, spostano nel cestino del sistema le loro copie locali dei file migrati. Sul server non si perde nulla, e dopo l&#39;aggiornamento tutto torna leggibile. I desktop vanno aggiornati prima del cloud, che distribuisce il flag acceso; in alternativa, finché restano dispositivi vecchi, si imposta <code>features.path_v2: false</code> nel profilo globale. Il workbench web è servito dal cloud ed è sempre aggiornato. I client del rilascio N leggono i due formati e, collegati a un cloud aggiornato, ricevono il flag acceso: scrivono <code>enc2</code> ma non migrano.</p>`,39)])])}const v=o(c,[["render",n]]);export{g as __pageData,v as default};
